import json,csv
with open('json/event.json') as f: events={r['event_id']:r['event_name'] for r in json.load(f)['records']}
with open('json/expense.json') as f: expenses=json.load(f)['records']
with open('csv/budget.csv') as f: budgets=list(csv.DictReader(f))
budget_event={b['budget_id']:b['link_to_event'] for b in budgets}
costs={}
for e in expenses:
  bid=e.get('link_to_budget')
  if bid:
    eid=budget_event.get(bid)
    if eid: costs[eid]=costs.get(eid,0)+float(e['cost'])
for eid,amt in costs.items(): print(events.get(eid,'?'), amt)
min_eid=min(costs,key=costs.get)
